command:
// ==========================================
// LUNAS WIRKUNG: HYPNOTISCHER BLICK (BRONA)
//
// - genau ein Ziel
// - Dauer: QS Minuten
// - Konzentrationseffekt auf dem Wirkenden
// - Opfer-Effekt auf dem Ziel
// - Ziel erhält core.statusId "stunned"
// - kein zusätzlicher Bewegungs-/Schadenswächter
// - Ziel gespeichert, kein erneutes Target
// - gekoppelte Effektanlage über Block 6
// - atomarer Rollback bei Teilfehlern
// - streng geheime Karte an GM, Wirkenden und Zielbesitzer
// - roter GM-Button „Effekt anwenden“
// ==========================================

(async function () {
const macroUuid = this?.uuid || null;

// +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++

const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const frameworkFehlt = !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.QS?.Ermitteln ||
    !globalThis.DSK?.Token?.Finde || !globalThis.DSK?.Target?.Merken ||
    !globalThis.DSK?.Target?.Finden || !globalThis.DSK?.Target?.Actor ||
    !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
    !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
    !globalThis.DSK?.Empfaenger?.GMUndBesitzer ||
    !globalThis.DSK?.GabenUI?.GMMakroButton ||
    !globalThis.DSK?.GabenUI?.AnfrageKartenInhalt ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

if (frameworkFehlt) {
    const fwMacro = await fromUuid(frameworkUuid);
    if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
    await fwMacro.execute(); await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;
if (!DSK_FW?.Effekt?.Anwenden || !DSK_FW?.QS?.Ermitteln ||
    !DSK_FW?.Token?.Finde || !DSK_FW?.Target?.Merken ||
    !DSK_FW?.Target?.Finden || !DSK_FW?.Target?.Actor ||
    !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
    !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
    !DSK_FW?.Empfaenger?.GMUndBesitzer ||
    !DSK_FW?.GabenUI?.GMMakroButton ||
    !DSK_FW?.GabenUI?.AnfrageKartenInhalt ||
    !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!");

// +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++++++

const gabenName = "Hypnotischer Blick", vollerName = "Hypnotischer Blick (Brona)", ahne = "Brona";
const casterEffektName = `${vollerName} - Konzentration`, targetEffektName = `${vollerName} - Opfer`;
const endeKey = "hypnotischerBlickBrona", flagKey = "pendingHypnotischerBlickBrona";
const endeText = "Der hypnotische Blick bricht ab. Die Erstarrung löst sich und das Ziel kann wieder frei handeln.";

DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

// +++ 3 - HELFER ++++++++++++++++++++++++++++++++++++++++++++++

const raeumeQSAuf = async actor => {
    if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
    if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
};

const ladeZiel = async daten => {
    if (!daten) return { token: null, actor: null };
    const token = await DSK_FW.Target.Finden(daten);
    return { token, actor: token?.actor || await DSK_FW.Target.Actor(daten) };
};

const whisperZiele = (casterActor, targetActor, anfragenderUserId = null) => {
    const ids = new Set([
        ...DSK_FW.Empfaenger.GMUndBesitzer(casterActor, { anfragenderUserId }),
        ...DSK_FW.Empfaenger.GMUndBesitzer(targetActor, { anfragenderUserId })
    ]);
    return [...ids].filter(id => game.users.get(id));
};

const beschreibungFuer = (casterName, targetName) =>
    `<b>${casterName}</b> blickt <b>${targetName}</b> tief in die Augen.` +
    `<br><br><b>Streng geheim:</b> Das Ziel verliert sich in den Augen des Vampirs und bleibt völlig reglos stehen.` +
    `<br><br>Der Grund für die plötzliche Regungslosigkeit soll gegenüber den übrigen Mitspielern verborgen bleiben.`;

const entferneAlteEffekte = async (casterActor, targetActor) => {
    const casterEffekte = casterActor.effects.filter(e => (e.name || e.label || "") === casterEffektName);
    const targetEffekte = targetActor.effects.filter(e => (e.name || e.label || "") === targetEffektName);

    if (casterEffekte.length) {
        await casterActor.deleteEmbeddedDocuments("ActiveEffect", casterEffekte.map(e => e.id));
    }
    if (targetEffekte.length) {
        await targetActor.deleteEmbeddedDocuments("ActiveEffect", targetEffekte.map(e => e.id));
    }
};

// +++ 4 - GEKOPPELTE EFFEKTE ÜBER BLOCK 6 ++++++++++++++++++++

const wendeHypnoseAn = async ({ casterActor, casterName, targetActor, targetName, qs, verbindungsId }) => {
    if (!casterActor || !targetActor || !verbindungsId) return false;

    await entferneAlteEffekte(casterActor, targetActor);

    const dauerSekunden = qs * 60;
    const wirkungsende = {
        sfName: endeKey,
        basisEffektName: vollerName,
        beschreibungFuerEnde: endeText
    };

    let casterEffekt = null, targetEffekt = null;

    try {
        casterEffekt = await DSK_FW.Effekt.Anwenden({
            name: casterEffektName, ahne,
            beschreibung: `Du hältst den hypnotischen Blick auf <b>${targetName}</b> gerichtet. Wird der Blick unterbrochen, endet die Wirkung sofort!`,
            gabeZiel: "", qs, ziel: casterActor,
            duration: { seconds: dauerSekunden, startTime: game.time.worldTime },
            showIcon: 1,
            flags: { dsk: {
                isHypnotischerBlickCaster: true, casterUuid: casterActor.uuid,
                qs, verbindungsId, partnerUuid: targetActor.uuid, wirkungsende
            }}
        });

        if (!casterEffekt) throw new Error("Konzentrationseffekt konnte nicht angelegt werden.");

        targetEffekt = await DSK_FW.Effekt.Anwenden({
            name: targetEffektName, ahne,
            beschreibung: `Du hast dich in den Augen von <b>${casterName}</b> verloren. Du bist völlig reglos.`,
            gabeZiel: "", qs, ziel: targetActor,
            duration: { seconds: dauerSekunden, startTime: game.time.worldTime },
            showIcon: 1,
            flags: {
                core: { statusId: "stunned" },
                dsk: {
                    isHypnotischerBlickOpfer: true, casterUuid: casterActor.uuid,
                    qs, verbindungsId, partnerUuid: casterActor.uuid, wirkungsende
                }
            }
        });

        if (!targetEffekt) throw new Error("Opfereffekt konnte nicht angelegt werden.");

        const casterEnde = casterEffekt.getFlag("dsk", "wirkungsende");
        const targetEnde = targetEffekt.getFlag("dsk", "wirkungsende");

        const casterKorrekt =
            casterEffekt.getFlag("dsk", "isHypnotischerBlickCaster") === true &&
            casterEffekt.getFlag("dsk", "verbindungsId") === verbindungsId &&
            casterEffekt.getFlag("dsk", "partnerUuid") === targetActor.uuid &&
            casterEnde?.sfName === endeKey &&
            casterEnde?.basisEffektName === vollerName;

        const targetKorrekt =
            targetEffekt.getFlag("core", "statusId") === "stunned" &&
            targetEffekt.getFlag("dsk", "isHypnotischerBlickOpfer") === true &&
            targetEffekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
            targetEffekt.getFlag("dsk", "verbindungsId") === verbindungsId &&
            targetEffekt.getFlag("dsk", "partnerUuid") === casterActor.uuid &&
            targetEnde?.sfName === endeKey &&
            targetEnde?.basisEffektName === vollerName;

        if (!casterKorrekt || !targetKorrekt) throw new Error("Die Hypnose wurde nicht vollständig angelegt.");
        return true;

    } catch (error) {
        console.error("Hypnotischer Blick: Gekoppelte Effektanlage fehlgeschlagen.", {
            casterActor: casterActor.name, targetActor: targetActor.name, verbindungsId, error
        });

        if (targetEffekt) try { await targetEffekt.delete(); } catch {}
        if (casterEffekt) try { await casterEffekt.delete(); } catch {}
        return false;
    }
};

// +++ 5 - ÖFFENTLICHE WIRKUNGSKARTE +++++++++++++++++++++++++++

const erstelleWirkungskarte = async ({
    casterName, targetName, qs, beschreibung, gmLink, gmBereich
}) => DSK_FW.GabenUI.AnfrageKarteErstellen({
    gabenName: vollerName, ahne, beschreibung, wirkender: casterName,
    ziele: [{ name: targetName, rolle: "Betroffenes Ziel" }],
    misserfolge: [], dauerText: `${qs} Minuten`,
    gmLink, gmBereich,
    anfragenderUserId: game.user.id
});

// +++ 6 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++++++

const verarbeiteAnfrage = async (casterActor, daten) => {
    if (!game.user.isGM || !casterActor || !daten) return false;
    if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) return false;

    if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
        ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
        return false;
    }

    const casterToken = DSK_FW.Token.Finde(casterActor, daten.casterTokenId, daten.casterTokenUuid);
    if (!casterToken) {
        ui.notifications.warn(`Luna sagt 🌙: Der Token von „${casterActor.name}“ wurde nicht gefunden!`);
        return false;
    }

    const { actor: targetActor } = await ladeZiel(daten.target);
    const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
    const targetName = daten.target?.name || targetActor?.name || "Unbekanntes Ziel";
    const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));

    const erfolgreich = Boolean(
        targetActor &&
        await wendeHypnoseAn({
            casterActor, casterName, targetActor, targetName, qs,
            verbindungsId: daten.verbindungsId
        })
    );

    await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
        messageId: daten.messageId,
        gabenName: "Heimliche Hypnose", ahne,
        beschreibung: daten.beschreibung,
        wirkender: casterName,
        ziele: erfolgreich ? [{ name: targetName, rolle: "Betroffenes Ziel" }] : [],
        misserfolge: erfolgreich ? [] : [{ name: targetName }],
        dauerText: `${qs} Minuten`, erfolgreich
    });

    if (erfolgreich) ui.notifications.info(`Luna sagt 🌙: Hypnotischer Blick wurde auf ${targetName} angewendet.`);
    else ui.notifications.error("Luna sagt 🌙: Hypnotischer Blick konnte nicht vollständig angewendet werden!");

    return true;
};

// +++ 7 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++++++

if (game.user.isGM) {
    const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

    if (anfragen.length) {
        for (const actor of anfragen) {
            const daten = DSK_FW.GMAnfrage.Lesen(actor, flagKey);
            if (daten && await verarbeiteAnfrage(actor, daten)) {
                await DSK_FW.GMAnfrage.Loeschen(actor, flagKey);
            }
        }
        return;
    }
}

// +++ 8 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++++++

let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;
if (!casterActor) casterActor =
    canvas.tokens.placeables.map(t => t.actor).find(a => a?.getFlag("world", "letzteGabenQS") !== undefined) ||
    game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined) || null;

if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");
if (!game.user.isGM && !casterActor.isOwner) return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");

const casterToken = DSK_FW.Token.Finde(casterActor);
if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!");

const casterName = DSK_FW.ResolveTokenName(casterActor);
const qs = DSK_FW.QS.Ermitteln({
    actor: casterActor, gabenName,
    suchbegriffe: ["Hypnotischer Blick Probe", "Hypnotischer Blick"],
    testDataObj: typeof testData !== "undefined" ? testData : null,
    fallback: 0, protokollieren: true
});

if (qs <= 0) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.warn("Luna sagt 🌙: Die Probe ist fehlgeschlagen oder die Qualitätsstufe wurde nicht gefunden!");
}

// +++ 9 - ZIEL PRÜFEN +++++++++++++++++++++++++++++++++++++++++

const targets = Array.from(game.user.targets || []);
if (targets.length !== 1) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.warn("Luna sagt 🌙: Bitte wähle genau ein Ziel für den hypnotischen Blick!");
}

const targetToken = targets[0], targetActor = targetToken?.actor;
if (!targetActor) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.warn("Luna sagt 🌙: Das gewählte Ziel besitzt keinen gültigen Akteur!");
}

const targetDaten = DSK_FW.Target.Merken(targetToken);
if (!targetDaten) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.warn("Luna sagt 🌙: Das gewählte Ziel konnte nicht gespeichert werden!");
}

const targetName = targetDaten.name;
const beschreibung = beschreibungFuer(casterName, targetName);
const gmLink = DSK_FW.GabenUI.GMMakroButton(
    macroUuid, "Effekt anwenden",
    "Das Makro muss durch die Spielleitung ausgeführt werden."
);

// +++ 10 - GEHEIME KARTE + GM-ANFRAGE +++++++++++++++++++++++++

const nachricht = await erstelleWirkungskarte({
    casterName, targetName, qs, beschreibung,
    gmLink, gmBereich: !game.user.isGM
});

if (!nachricht) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.error("Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!");
}

const anfrageDaten = {
    casterUuid: casterActor.uuid, casterName,
    casterTokenId: casterToken.id,
    casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null,
    target: targetDaten, qs,
    verbindungsId: `hypnotischer-blick-${Date.now()}-${foundry.utils.randomID()}`,
    beschreibung, sceneId: canvas.scene?.id || null,
    messageId: nachricht.id, macroUuid, erstellt: Date.now()
};

if (game.user.isGM) {
    await verarbeiteAnfrage(casterActor, anfrageDaten);
    await raeumeQSAuf(casterActor);
    return;
}

await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);
await raeumeQSAuf(casterActor);
ui.notifications.info("Luna sagt 🌙: Hypnotischer Blick wurde bei der Spielleitung zur Anwendung beantragt.");

}).call(this);
